export const arteQuestions: Question[] = [
  {"id":"arte-vest-v1-mc-i-01","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"História da arte","subtopic":"Renascimento","difficulty":"iniciante","type":"multiple-choice","statement":"Em uma pintura renascentista, linhas do piso e das paredes parecem convergir para\n    um mesmo ponto ao fundo, fazendo a cena parecer tridimensional.\n\n    O recurso visual utilizado é:","alternatives":[{"id":"A","text":"perspectiva linear"},{"id":"B","text":"contraste cromático"},{"id":"C","text":"montagem cinematográfica"},{"id":"D","text":"improvisação corporal"}],"correctAnswer":"A","explanation":"A perspectiva linear organiza linhas de fuga em torno de um ou mais pontos, criando uma ilusão geométrica de profundidade.","alternativeExplanations":{"A":"Correta. A perspectiva linear organiza linhas de fuga em torno de um ou mais pontos, criando uma ilusão geométrica de profundidade.","B":"Contraste cromático trabalha diferenças de cor e não organiza, por si só, a profundidade geométrica descrita.","C":"Montagem é um procedimento audiovisual baseado na ordenação de planos.","D":"Improvisação pertence ao campo da criação em dança ou performance."},"tags":["historia-da-arte","renascimento","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["historia-da-arte","renascimento","perspectiva"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-02","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte brasileira","subtopic":"Barroco","difficulty":"iniciante","type":"multiple-choice","statement":"Uma igreja colonial mineira reúne talha dourada, esculturas religiosas, curvas,\n    ornamentação intensa e forte efeito dramático no interior.\n\n    Esse conjunto está associado ao:","alternatives":[{"id":"A","text":"Neoclassicismo francês"},{"id":"B","text":"Barroco mineiro"},{"id":"C","text":"Minimalismo"},{"id":"D","text":"Construtivismo russo"}],"correctAnswer":"B","explanation":"O Barroco mineiro articula arquitetura, escultura e ornamentação religiosa em contexto colonial, com forte expressividade e adaptação local.","alternativeExplanations":{"A":"O exemplo está ligado ao contexto colonial brasileiro e ao barroco religioso.","B":"Correta. O Barroco mineiro articula arquitetura, escultura e ornamentação religiosa em contexto colonial, com forte expressividade e adaptação local.","C":"Minimalismo privilegia redução formal, oposta à ornamentação descrita.","D":"É um movimento do século XX com outro contexto histórico e visual."},"tags":["arte-brasileira","barroco","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-brasileira","barroco","patrimonio-colonial"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-03","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Modernismo","subtopic":"Semana de 1922","difficulty":"iniciante","type":"multiple-choice","statement":"Um artista brasileiro afirma que não deseja simplesmente copiar modelos estrangeiros,\n    mas absorvê-los, transformá-los e combiná-los com experiências brasileiras.\n\n    A ideia se aproxima da:","alternatives":[{"id":"A","text":"perspectiva linear renascentista"},{"id":"B","text":"quarta parede teatral"},{"id":"C","text":"Antropofagia modernista"},{"id":"D","text":"profundidade de campo"}],"correctAnswer":"C","explanation":"A antropofagia modernista propõe apropriação crítica de referências externas para produzir formas culturais próprias.","alternativeExplanations":{"A":"Esse conceito trata de construção espacial na imagem.","B":"A quarta parede é uma convenção da representação cênica.","C":"Correta. A antropofagia modernista propõe apropriação crítica de referências externas para produzir formas culturais próprias.","D":"Profundidade de campo pertence à linguagem fotográfica/cinematográfica."},"tags":["modernismo","antropofagia","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["modernismo","antropofagia","apropriacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-04","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Artes visuais","subtopic":"Composição","difficulty":"iniciante","type":"multiple-choice","statement":"Em um cartaz, uma pequena forma amarela aparece sobre um fundo quase todo azul-escuro.\n    A diferença intensa de cor faz a forma chamar imediatamente a atenção.\n\n    O recurso predominante é:","alternatives":[{"id":"A","text":"ritmo musical"},{"id":"B","text":"montagem cinematográfica"},{"id":"C","text":"patrimônio imaterial"},{"id":"D","text":"contraste visual"}],"correctAnswer":"D","explanation":"Contraste ocorre quando diferenças de cor, forma, tamanho, textura ou luminosidade geram destaque e tensão visual.","alternativeExplanations":{"A":"Ritmo musical organiza sons no tempo.","B":"Montagem ordena planos audiovisuais.","C":"Patrimônio imaterial se refere a práticas e saberes culturais vivos.","D":"Correta. Contraste ocorre quando diferenças de cor, forma, tamanho, textura ou luminosidade geram destaque e tensão visual."},"tags":["artes-visuais","composicao","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["artes-visuais","composicao","contraste"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-05","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Música","subtopic":"Elementos sonoros","difficulty":"iniciante","type":"multiple-choice","statement":"Em uma canção, palmas repetem uma sequência de durações e acentos que organiza\n    a pulsação percebida pelo ouvinte.\n\n    O elemento musical mais diretamente destacado é:","alternatives":[{"id":"A","text":"ritmo"},{"id":"B","text":"perspectiva"},{"id":"C","text":"profundidade de campo"},{"id":"D","text":"quarta parede"}],"correctAnswer":"A","explanation":"Ritmo organiza durações, pulsações, acentos e silêncios ao longo do tempo.","alternativeExplanations":{"A":"Correta. Ritmo organiza durações, pulsações, acentos e silêncios ao longo do tempo.","B":"Perspectiva é um conceito visual.","C":"Profundidade de campo é um conceito fotográfico.","D":"Quarta parede é uma convenção teatral."},"tags":["musica","ritmo","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["musica","ritmo","elementos-sonoros"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-06","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Teatro","subtopic":"Representação","difficulty":"iniciante","type":"multiple-choice","statement":"Em uma peça realista, os atores agem como se o público não estivesse presente,\n    mantendo a ilusão de que existe uma parede invisível separando palco e plateia.\n\n    Essa convenção é chamada de:","alternatives":[{"id":"A","text":"montagem"},{"id":"B","text":"quarta parede"},{"id":"C","text":"perspectiva linear"},{"id":"D","text":"improvisação em dança"}],"correctAnswer":"B","explanation":"A quarta parede é a separação imaginária entre o espaço ficcional da cena e os espectadores.","alternativeExplanations":{"A":"Montagem, nesse sentido, pertence à linguagem audiovisual.","B":"Correta. A quarta parede é a separação imaginária entre o espaço ficcional da cena e os espectadores.","C":"Perspectiva é uma técnica de representação espacial.","D":"Improvisação corporal é outro procedimento artístico."},"tags":["teatro","quarta-parede","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["teatro","quarta-parede","representacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-07","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Dança","subtopic":"Criação","difficulty":"iniciante","type":"multiple-choice","statement":"Uma coreógrafa define regras simples — usar apenas movimentos circulares e responder\n    ao gesto do colega —, mas os bailarinos decidem a sequência exata enquanto dançam.\n\n    O procedimento é um exemplo de:","alternatives":[{"id":"A","text":"perspectiva linear"},{"id":"B","text":"montagem cinematográfica"},{"id":"C","text":"improvisação em dança"},{"id":"D","text":"patrimônio material"}],"correctAnswer":"C","explanation":"Na improvisação, decisões corporais podem ser tomadas durante a execução, muitas vezes dentro de regras ou estímulos previamente definidos.","alternativeExplanations":{"A":"É um procedimento das artes visuais.","B":"Refere-se à organização de planos no audiovisual.","C":"Correta. Na improvisação, decisões corporais podem ser tomadas durante a execução, muitas vezes dentro de regras ou estímulos previamente definidos.","D":"O caso trata de criação corporal em tempo real."},"tags":["danca","improvisacao","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["danca","improvisacao","criacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-08","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cinema","subtopic":"Montagem","difficulty":"iniciante","type":"multiple-choice","statement":"Um filme mostra primeiro uma personagem olhando para fora da tela e, em seguida,\n    corta para um trem se aproximando. A relação entre os dois planos faz o espectador\n    entender o que ela vê.\n\n    O recurso central é:","alternatives":[{"id":"A","text":"profundidade de campo"},{"id":"B","text":"perspectiva linear"},{"id":"C","text":"ritmo musical"},{"id":"D","text":"montagem cinematográfica"}],"correctAnswer":"D","explanation":"A montagem cria relações entre planos sucessivos, construindo continuidade, tempo e sentido que não estão em uma imagem isolada.","alternativeExplanations":{"A":"Profundidade de campo trata das faixas de nitidez dentro do plano.","B":"Perspectiva organiza espaço em uma imagem estática.","C":"O caso é construído pela sucessão de planos visuais.","D":"Correta. A montagem cria relações entre planos sucessivos, construindo continuidade, tempo e sentido que não estão em uma imagem isolada."},"tags":["cinema","montagem","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cinema","montagem","continuidade"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-09","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Fotografia","subtopic":"Exposição","difficulty":"iniciante","type":"multiple-choice","statement":"Em um retrato, o rosto está nítido enquanto o fundo aparece fortemente desfocado.\n\n    O efeito está diretamente relacionado à:","alternatives":[{"id":"A","text":"profundidade de campo"},{"id":"B","text":"montagem"},{"id":"C","text":"perspectiva atmosférica"},{"id":"D","text":"patrimônio imaterial"}],"correctAnswer":"A","explanation":"Profundidade de campo é a faixa de distâncias que aparece aceitavelmente nítida na imagem.","alternativeExplanations":{"A":"Correta. Profundidade de campo é a faixa de distâncias que aparece aceitavelmente nítida na imagem.","B":"Montagem relaciona planos em sequência.","C":"O caso descreve nitidez focal, não gradação de cor pela distância.","D":"É um conceito cultural, não fotográfico."},"tags":["fotografia","profundidade-de-campo","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["fotografia","profundidade-de-campo","foco"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-10","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cultura popular","subtopic":"Patrimônio imaterial","difficulty":"iniciante","type":"multiple-choice","statement":"Uma comunidade transmite entre gerações um modo tradicional de preparar alimento,\n    acompanhado de celebrações, histórias e conhecimentos compartilhados.\n\n    Esse conjunto pode ser reconhecido como:","alternatives":[{"id":"A","text":"perspectiva linear"},{"id":"B","text":"patrimônio cultural imaterial"},{"id":"C","text":"montagem cinematográfica"},{"id":"D","text":"arte relacional"}],"correctAnswer":"B","explanation":"Patrimônio imaterial inclui saberes, práticas, celebrações e formas de expressão reconhecidas por grupos como referências de sua identidade.","alternativeExplanations":{"A":"É uma técnica visual.","B":"Correta. Patrimônio imaterial inclui saberes, práticas, celebrações e formas de expressão reconhecidas por grupos como referências de sua identidade.","C":"É um procedimento audiovisual.","D":"É uma categoria da arte contemporânea ligada à interação."},"tags":["cultura-popular","patrimonio","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cultura-popular","patrimonio-imaterial","saberes"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-11","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte contemporânea","subtopic":"Participação","difficulty":"iniciante","type":"multiple-choice","statement":"Uma obra só se completa quando visitantes sentam-se a uma mesa, conversam\n    e compartilham uma refeição organizada pelo artista.\n\n    O exemplo aproxima-se da:","alternatives":[{"id":"A","text":"perspectiva linear"},{"id":"B","text":"montagem cinematográfica"},{"id":"C","text":"arte relacional"},{"id":"D","text":"barroco mineiro"}],"correctAnswer":"C","explanation":"Na arte relacional, encontros e interações humanas podem constituir parte central da própria obra.","alternativeExplanations":{"A":"O foco não está em representar profundidade.","B":"Não há organização de planos audiovisuais.","C":"Correta. Na arte relacional, encontros e interações humanas podem constituir parte central da própria obra.","D":"O exemplo pertence a práticas contemporâneas participativas."},"tags":["arte-contemporanea","participacao","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-contemporanea","arte-relacional","participacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-i-12","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Linguagem visual","subtopic":"Cor","difficulty":"iniciante","type":"multiple-choice","statement":"Em um círculo cromático tradicional, azul e laranja ocupam posições opostas.\n    Quando colocados lado a lado, produzem forte contraste.\n\n    Eles são chamados de cores:","alternatives":[{"id":"A","text":"análogas"},{"id":"B","text":"neutras"},{"id":"C","text":"monocromáticas"},{"id":"D","text":"complementares"}],"correctAnswer":"D","explanation":"Cores complementares ocupam posições opostas no círculo cromático e tendem a produzir contraste intenso quando justapostas.","alternativeExplanations":{"A":"Cores análogas aparecem próximas no círculo cromático.","B":"Azul e laranja não formam, nesse contexto, um par de cores neutras.","C":"Monocromia trabalha variações de uma mesma cor.","D":"Correta. Cores complementares ocupam posições opostas no círculo cromático e tendem a produzir contraste intenso quando justapostas."},"tags":["linguagem-visual","cor","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["linguagem-visual","cor","cores-complementares"],"origin":"nabulab"},

  {"id":"arte-vest-v1-vf-i-01","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Modernismo","subtopic":"Semana de 1922","difficulty":"iniciante","type":"true-false","statement":"A antropofagia modernista defendia a assimilação crítica de referências estrangeiras,\n    e não uma simples rejeição de tudo que viesse de fora.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"O gesto antropofágico propõe devorar simbolicamente influências, transformando-as a partir de experiências brasileiras.","alternativeExplanations":{"V":"Correto. A lógica é de apropriação e recriação.","F":"Incorreto. A proposta não é isolamento cultural."},"tags":["modernismo","antropofagia","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["modernismo","antropofagia","recriacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-02","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Artes visuais","subtopic":"Composição","difficulty":"iniciante","type":"true-false","statement":"Contraste visual só pode ser produzido por diferenças de cor; escala, forma e textura não alteram o destaque entre elementos.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Contraste também pode resultar de escala, forma, textura, luminosidade e outras relações visuais.","alternativeExplanations":{"V":"Incorreto. O conceito é mais amplo que contraste cromático.","F":"Correto. Limitar contraste à cor torna a afirmação falsa."},"tags":["artes-visuais","composicao","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["artes-visuais","contraste","elementos-visuais"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-03","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Música","subtopic":"Elementos sonoros","difficulty":"iniciante","type":"true-false","statement":"Ritmo musical envolve organização temporal de sons e silêncios, não apenas a velocidade da música.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Andamento diz respeito à velocidade geral; ritmo envolve padrões de duração e acentuação.","alternativeExplanations":{"V":"Correto. Ritmo e andamento se relacionam, mas não são sinônimos.","F":"Incorreto. Reduzir ritmo à velocidade confunde conceitos distintos."},"tags":["musica","ritmo","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["musica","ritmo","andamento"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-04","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Teatro","subtopic":"Representação","difficulty":"iniciante","type":"true-false","statement":"A quarta parede é uma estrutura física obrigatória construída entre palco e plateia.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"A quarta parede é uma convenção imaginária de representação, não uma parede material necessária.","alternativeExplanations":{"V":"Incorreto. Trata-se de uma convenção cênica.","F":"Correto. Um teatro pode nem ter separação física e ainda trabalhar com essa convenção."},"tags":["teatro","quarta-parede","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["teatro","quarta-parede","metateatro"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-05","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Dança","subtopic":"Criação","difficulty":"iniciante","type":"true-false","statement":"Improvisar em dança não significa obrigatoriamente ausência de regras;\n    a criação pode ocorrer dentro de restrições definidas previamente.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Improvisações podem usar tarefas, limites espaciais, qualidades de movimento ou sinais como estrutura para decisões em tempo real.","alternativeExplanations":{"V":"Correto. Liberdade e restrição podem coexistir na improvisação.","F":"Incorreto. Improvisação não é sinônimo de movimento totalmente aleatório."},"tags":["danca","improvisacao","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["danca","improvisacao","regras-de-criacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-06","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cinema","subtopic":"Montagem","difficulty":"iniciante","type":"true-false","statement":"Montagem cinematográfica significa apenas gravar uma tomada longa sem cortes.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Montagem envolve seleção e organização de planos; ela não se reduz a uma tomada contínua.","alternativeExplanations":{"V":"Incorreto. A afirmação nega justamente a operação de montagem.","F":"Correto. Montagem trabalha relações entre planos."},"tags":["cinema","montagem","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cinema","montagem","sentido"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-07","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Fotografia","subtopic":"Exposição","difficulty":"iniciante","type":"true-false","statement":"Uma abertura maior, como f/2, tende a produzir profundidade de campo menor\n    do que uma abertura menor, como f/11, mantidas as demais condições.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Aberturas amplas reduzem a faixa de nitidez, enquanto aberturas menores geralmente ampliam a profundidade de campo.","alternativeExplanations":{"V":"Correto. Esse é um dos fatores que controlam a profundidade de campo.","F":"Incorreto. A relação entre abertura e profundidade de campo foi invertida."},"tags":["fotografia","profundidade-de-campo","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["fotografia","abertura","profundidade-de-campo"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-08","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cultura popular","subtopic":"Patrimônio imaterial","difficulty":"iniciante","type":"true-false","statement":"Patrimônio cultural imaterial é formado apenas por prédios, monumentos e objetos antigos.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Patrimônio imaterial inclui saberes, celebrações, práticas e formas de expressão.","alternativeExplanations":{"V":"Incorreto. Prédios e objetos pertencem ao campo material.","F":"Correto. O enunciado confunde patrimônio material e imaterial."},"tags":["cultura-popular","patrimonio","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cultura-popular","patrimonio-imaterial","transmissao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-09","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte contemporânea","subtopic":"Participação","difficulty":"iniciante","type":"true-false","statement":"Em algumas obras contemporâneas, a participação do público pode fazer parte\n    do próprio processo artístico, e não apenas da observação posterior.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Práticas participativas transformam o espectador em colaborador, participante ou agente da situação criada pela obra.","alternativeExplanations":{"V":"Correto. A obra pode depender da interação para acontecer.","F":"Incorreto. O público nem sempre ocupa posição apenas contemplativa."},"tags":["arte-contemporanea","participacao","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-contemporanea","participacao","publico"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-10","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Linguagem visual","subtopic":"Cor","difficulty":"iniciante","type":"true-false","statement":"Cores complementares são sempre vizinhas no círculo cromático.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Em modelos cromáticos tradicionais, complementares ocupam posições opostas, não vizinhas.","alternativeExplanations":{"V":"Incorreto. Cores próximas são chamadas de análogas.","F":"Correto. A relação complementar foi descrita de forma errada."},"tags":["linguagem-visual","cor","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["linguagem-visual","cor","contraste-cromatico"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-11","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"História da arte","subtopic":"Renascimento","difficulty":"iniciante","type":"true-false","statement":"A perspectiva linear foi usada no Renascimento para criar a impressão de profundidade\n    em superfícies bidimensionais.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"A técnica organiza o espaço pictórico por relações geométricas e pontos de fuga, reforçando a ilusão de profundidade.","alternativeExplanations":{"V":"Correto. Ela foi um recurso importante da representação espacial renascentista.","F":"Incorreto. A técnica está diretamente ligada à construção visual de profundidade."},"tags":["historia-da-arte","renascimento","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["historia-da-arte","renascimento","espaco-pictorico"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-i-12","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte brasileira","subtopic":"Barroco","difficulty":"iniciante","type":"true-false","statement":"O Barroco mineiro surgiu no século XX como parte das vanguardas modernistas brasileiras.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"O Barroco mineiro está ligado ao período colonial, especialmente aos séculos XVIII e início do XIX.","alternativeExplanations":{"V":"Incorreto. O contexto histórico está deslocado em mais de um século.","F":"Correto. O movimento não pertence ao modernismo do século XX."},"tags":["arte-brasileira","barroco","vestibulares","iniciante"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-brasileira","barroco","contexto-historico"],"origin":"nabulab"},

  {"id":"arte-vest-v1-mc-m-01","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Música","subtopic":"Elementos sonoros","difficulty":"medio","type":"multiple-choice","statement":"Uma mesma melodia é tocada duas vezes. Na segunda execução, o andamento é mantido,\n    mas alguns acentos e durações são deslocados, criando sensação rítmica diferente.\n\n    O exemplo mostra que:","alternatives":[{"id":"A","text":"ritmo depende da organização das durações e acentos, não apenas do andamento"},{"id":"B","text":"ritmo e melodia são exatamente a mesma coisa"},{"id":"C","text":"qualquer mudança rítmica exige mudar a tonalidade"},{"id":"D","text":"manter o andamento impede qualquer alteração rítmica"}],"correctAnswer":"A","explanation":"Mesmo com velocidade constante, a distribuição temporal de ataques, pausas e acentuações pode alterar o caráter rítmico.","alternativeExplanations":{"A":"Correta. Mesmo com velocidade constante, a distribuição temporal de ataques, pausas e acentuações pode alterar o caráter rítmico.","B":"Melodia envolve sucessão de alturas; ritmo organiza durações.","C":"Tonalidade e ritmo podem variar independentemente.","D":"O caso demonstra o contrário."},"tags":["musica","ritmo","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["musica","ritmo","analise-auditiva"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-02","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Teatro","subtopic":"Representação","difficulty":"medio","type":"multiple-choice","statement":"Em determinado espetáculo, um personagem interrompe a ação, acende a luz da plateia\n    e pergunta aos espectadores se acreditam no que acabaram de ver.\n\n    O efeito principal dessa escolha é:","alternatives":[{"id":"A","text":"restaurar automaticamente o realismo ilusionista"},{"id":"B","text":"tornar visível a própria convenção teatral e convidar o público a refletir sobre a representação"},{"id":"C","text":"eliminar toda possibilidade de narrativa"},{"id":"D","text":"transformar o espetáculo em cinema"}],"correctAnswer":"B","explanation":"Ao romper a ilusão cênica, o espetáculo chama atenção para o fato de que aquilo que se vê é uma construção teatral.","alternativeExplanations":{"A":"A ação faz justamente o contrário.","B":"Correta. Ao romper a ilusão cênica, o espetáculo chama atenção para o fato de que aquilo que se vê é uma construção teatral.","C":"Narrativa e metateatro podem coexistir.","D":"A presença de comentário metateatral não altera o meio artístico."},"tags":["teatro","quarta-parede","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["teatro","quarta-parede","efeito-de-distanciamento"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-03","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Dança","subtopic":"Criação","difficulty":"medio","type":"multiple-choice","statement":"Dois bailarinos recebem a mesma instrução: \"aproxime-se do outro sem tocar\".\n    Em cada apresentação, eles criam trajetórias diferentes, mas mantêm a regra.\n\n    O exemplo mostra que:","alternatives":[{"id":"A","text":"improvisação exige repetir uma sequência fixa"},{"id":"B","text":"qualquer regra elimina a autoria do intérprete"},{"id":"C","text":"uma regra de improvisação pode organizar a criação sem determinar previamente todos os movimentos"},{"id":"D","text":"dança só existe quando há coreografia totalmente memorizada"}],"correctAnswer":"C","explanation":"A estrutura funciona como restrição produtiva: delimita possibilidades e, ao mesmo tempo, deixa decisões abertas aos intérpretes.","alternativeExplanations":{"A":"A sequência varia a cada apresentação.","B":"A decisão em tempo real continua sendo parte da criação.","C":"Correta. A estrutura funciona como restrição produtiva: delimita possibilidades e, ao mesmo tempo, deixa decisões abertas aos intérpretes.","D":"Práticas improvisacionais também constituem dança."},"tags":["danca","improvisacao","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["danca","improvisacao","estrutura-aberta"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-04","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cinema","subtopic":"Montagem","difficulty":"medio","type":"multiple-choice","statement":"A mesma imagem de um rosto neutro é montada, em versões diferentes, depois de um prato de comida,\n    de um caixão e de uma criança brincando. Espectadores atribuem emoções distintas ao rosto.\n\n    O experimento evidencia:","alternatives":[{"id":"A","text":"que o rosto muda fisicamente entre as versões"},{"id":"B","text":"que montagem só serve para encurtar filmes"},{"id":"C","text":"que espectadores ignoram a ordem dos planos"},{"id":"D","text":"a capacidade da montagem de orientar a interpretação de um plano pelo contexto criado pelos planos vizinhos"}],"correctAnswer":"D","explanation":"A relação entre imagens pode alterar o sentido percebido de uma mesma expressão, princípio associado ao chamado efeito Kuleshov.","alternativeExplanations":{"A":"A imagem do rosto permanece a mesma.","B":"Ela também constrói relações semânticas.","C":"A interpretação depende justamente da ordem e do contexto.","D":"Correta. A relação entre imagens pode alterar o sentido percebido de uma mesma expressão, princípio associado ao chamado efeito Kuleshov."},"tags":["cinema","montagem","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cinema","montagem","efeito-kuleshov"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-05","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Fotografia","subtopic":"Exposição","difficulty":"medio","type":"multiple-choice","statement":"Uma fotógrafa quer manter em foco uma pessoa a dois metros e uma paisagem distante.\n    Sem mudar a posição da câmera, qual ajuste tende a ajudar?","alternatives":[{"id":"A","text":"fechar a abertura, usando um número f maior"},{"id":"B","text":"abrir ao máximo a lente"},{"id":"C","text":"usar foco exclusivamente no ponto mais próximo possível"},{"id":"D","text":"aumentar a velocidade do obturador como único ajuste"}],"correctAnswer":"A","explanation":"Uma abertura menor tende a ampliar a profundidade de campo, aumentando a faixa aparente de nitidez.","alternativeExplanations":{"A":"Correta. Uma abertura menor tende a ampliar a profundidade de campo, aumentando a faixa aparente de nitidez.","B":"Abertura maior tende a reduzir a profundidade de campo.","C":"Isso não garante nitidez da paisagem distante.","D":"Velocidade influencia exposição e movimento, mas não amplia diretamente a profundidade de campo."},"tags":["fotografia","profundidade-de-campo","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["fotografia","abertura","controle-tecnico"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-06","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cultura popular","subtopic":"Patrimônio imaterial","difficulty":"medio","type":"multiple-choice","statement":"Uma festa tradicional passa a incorporar novos instrumentos e repertórios,\n    mas moradores continuam reconhecendo nela uma referência importante de sua memória coletiva.\n\n    Qual interpretação é mais adequada?","alternatives":[{"id":"A","text":"qualquer mudança elimina automaticamente o valor patrimonial"},{"id":"B","text":"patrimônio imaterial pode se transformar ao longo do tempo sem perder necessariamente seu vínculo comunitário"},{"id":"C","text":"patrimônio só existe quando registrado em museu"},{"id":"D","text":"apenas objetos antigos podem constituir patrimônio"}],"correctAnswer":"B","explanation":"Práticas culturais vivas são recriadas por seus participantes; salvaguarda não equivale a congelamento.","alternativeExplanations":{"A":"Mudança é parte normal de tradições vivas.","B":"Correta. Práticas culturais vivas são recriadas por seus participantes; salvaguarda não equivale a congelamento.","C":"Patrimônio imaterial reside também em práticas e conhecimentos vivos.","D":"O conceito inclui dimensões imateriais."},"tags":["cultura-popular","patrimonio","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cultura-popular","patrimonio","mudanca-cultural"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-07","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte contemporânea","subtopic":"Participação","difficulty":"medio","type":"multiple-choice","statement":"Duas exposições apresentam cadeiras. Na primeira, o público apenas observa o objeto.\n    Na segunda, visitantes são convidados a reorganizar as cadeiras e conversar,\n    e essas interações são registradas como parte da obra.\n\n    Qual diferença é central?","alternatives":[{"id":"A","text":"a segunda deixa de ser arte porque o público participa"},{"id":"B","text":"a primeira não possui qualquer forma visual"},{"id":"C","text":"na segunda, a relação entre participantes torna-se componente constitutivo do trabalho"},{"id":"D","text":"a segunda é necessariamente teatro tradicional"}],"correctAnswer":"C","explanation":"A materialidade das cadeiras funciona como suporte para uma situação social; o processo relacional integra o sentido da obra.","alternativeExplanations":{"A":"Participação pode ser um procedimento artístico deliberado.","B":"A cadeira continua sendo um objeto visual.","C":"Correta. A materialidade das cadeiras funciona como suporte para uma situação social; o processo relacional integra o sentido da obra.","D":"Interação participativa pode ocorrer em diferentes linguagens contemporâneas."},"tags":["arte-contemporanea","participacao","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-contemporanea","arte-relacional","processo"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-08","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Linguagem visual","subtopic":"Cor","difficulty":"medio","type":"multiple-choice","statement":"Um ilustrador utiliza predominantemente tons de azul e verde e insere um pequeno elemento\n    laranja no centro da composição.\n\n    Por que o laranja tende a ganhar destaque?","alternatives":[{"id":"A","text":"porque qualquer elemento central é sempre percebido primeiro, independentemente da cor"},{"id":"B","text":"porque azul e laranja são cores análogas"},{"id":"C","text":"porque contraste só existe entre preto e branco"},{"id":"D","text":"porque estabelece forte contraste cromático com o campo azulado, aproximando-se de uma relação complementar"}],"correctAnswer":"D","explanation":"Contrastes de matiz e complementaridade podem aumentar a saliência perceptiva de um elemento.","alternativeExplanations":{"A":"Posição ajuda, mas não explica sozinha o contraste descrito.","B":"Elas ocupam regiões opostas em modelos cromáticos tradicionais.","C":"Contraste também pode ocorrer entre matizes.","D":"Correta. Contrastes de matiz e complementaridade podem aumentar a saliência perceptiva de um elemento."},"tags":["linguagem-visual","cor","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["linguagem-visual","cor","contraste"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-09","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"História da arte","subtopic":"Renascimento","difficulty":"medio","type":"multiple-choice","statement":"Duas pinturas representam o mesmo interior. Na primeira, figuras e objetos parecem\n    distribuídos sem uma lógica espacial única. Na segunda, arquitetura, chão e personagens\n    convergem visualmente para um ponto, orientando o olhar do observador.\n\n    O que a segunda solução evidencia?","alternatives":[{"id":"A","text":"o uso de uma construção racionalizada do espaço por perspectiva linear"},{"id":"B","text":"a eliminação de qualquer simbolismo religioso"},{"id":"C","text":"a recusa renascentista da matemática"},{"id":"D","text":"a substituição da pintura pela escultura"}],"correctAnswer":"A","explanation":"A perspectiva linear cria coerência espacial por relações geométricas entre observador, plano pictórico e pontos de fuga.","alternativeExplanations":{"A":"Correta. A perspectiva linear cria coerência espacial por relações geométricas entre observador, plano pictórico e pontos de fuga.","B":"Perspectiva e temática religiosa podem coexistir.","C":"O recurso descrito depende justamente de relações geométricas.","D":"A comparação continua situada no campo pictórico."},"tags":["historia-da-arte","renascimento","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["historia-da-arte","renascimento","analise-visual"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-10","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte brasileira","subtopic":"Barroco","difficulty":"medio","type":"multiple-choice","statement":"Em uma análise de uma igreja colonial, um estudante observa que arquitetura, escultura,\n    pintura e talha foram pensadas de modo integrado para envolver emocionalmente o fiel.\n\n    Essa leitura é adequada porque o Barroco:","alternatives":[{"id":"A","text":"evita qualquer ornamentação para valorizar superfícies neutras"},{"id":"B","text":"frequentemente articula diferentes linguagens para produzir forte efeito sensorial e religioso"},{"id":"C","text":"rejeita completamente imagens religiosas"},{"id":"D","text":"depende exclusivamente de pintura a óleo sobre tela"}],"correctAnswer":"B","explanation":"A integração entre artes, teatralidade e dramaticidade é uma característica importante de muitas obras barrocas.","alternativeExplanations":{"A":"Essa descrição se aproxima mais de estéticas modernas minimalistas.","B":"Correta. A integração entre artes, teatralidade e dramaticidade é uma característica importante de muitas obras barrocas.","C":"Imagens sacras são centrais em grande parte do barroco colonial.","D":"O barroco envolve arquitetura, talha, escultura e outros meios."},"tags":["arte-brasileira","barroco","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-brasileira","barroco","integracao-das-artes"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-11","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Modernismo","subtopic":"Semana de 1922","difficulty":"medio","type":"multiple-choice","statement":"Um estudante diz que o Modernismo brasileiro de 1922 buscava \"apagar toda tradição\".\n    Outro observa que vários modernistas retomaram temas populares, indígenas e coloniais,\n    mas os reelaboraram em novas linguagens.\n\n    Qual avaliação é mais adequada?","alternatives":[{"id":"A","text":"o modernismo recusou qualquer tema brasileiro"},{"id":"B","text":"a Semana de 1922 foi um retorno integral às normas acadêmicas do século XIX"},{"id":"C","text":"o modernismo rompeu com convenções acadêmicas sem abandonar necessariamente o diálogo com tradições culturais"},{"id":"D","text":"a presença de tradição impede qualquer inovação estética"}],"correctAnswer":"C","explanation":"Ruptura estética pode coexistir com reinterpretação de tradições; modernistas revisitaram elementos do passado e da cultura brasileira.","alternativeExplanations":{"A":"O movimento valorizou intensamente debates sobre identidade e cultura brasileira.","B":"A Semana simboliza justamente contestação de convenções acadêmicas.","C":"Correta. Ruptura estética pode coexistir com reinterpretação de tradições; modernistas revisitaram elementos do passado e da cultura brasileira.","D":"Tradição pode ser reinterpretada de forma inovadora."},"tags":["modernismo","antropofagia","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["modernismo","semana-de-1922","tradicao-e-ruptura"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-m-12","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Artes visuais","subtopic":"Composição","difficulty":"medio","type":"multiple-choice","statement":"Um designer quer destacar um título sem aumentar muito seu tamanho. Ele reduz o contraste\n    dos demais elementos, cria maior espaço vazio ao redor do título e usa uma cor mais intensa nele.\n\n    O resultado depende principalmente de:","alternatives":[{"id":"A","text":"uma regra fixa segundo a qual o maior elemento sempre é o mais importante"},{"id":"B","text":"ausência de composição"},{"id":"C","text":"eliminação de qualquer relação entre figura e fundo"},{"id":"D","text":"relações de hierarquia visual construídas por contraste e organização espacial"}],"correctAnswer":"D","explanation":"Hierarquia visual surge da relação entre elementos; destaque pode ser produzido por cor, espaço, escala e posição.","alternativeExplanations":{"A":"Hierarquia pode ser construída por diferentes meios.","B":"As escolhas descritas são justamente decisões compositivas.","C":"O destaque depende da relação entre os elementos e o entorno.","D":"Correta. Hierarquia visual surge da relação entre elementos; destaque pode ser produzido por cor, espaço, escala e posição."},"tags":["artes-visuais","composicao","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["artes-visuais","composicao","hierarquia-visual"],"origin":"nabulab"},

  {"id":"arte-vest-v1-vf-m-01","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Dança","subtopic":"Criação","difficulty":"medio","type":"true-false","statement":"Em práticas improvisacionais, o intérprete pode também atuar como criador,\n    pois toma decisões compositivas durante a execução.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Escolhas de direção, duração, relação, intensidade e timing podem ser produzidas pelo performer em tempo real.","alternativeExplanations":{"V":"Correto. Execução e criação podem se sobrepor.","F":"Incorreto. A improvisação pode ampliar a agência compositiva do intérprete."},"tags":["danca","improvisacao","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["danca","improvisacao","autoria"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-02","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cinema","subtopic":"Montagem","difficulty":"medio","type":"true-false","statement":"Alterar a ordem dos mesmos planos não muda o sentido de uma sequência cinematográfica, porque cada plano possui significado completamente independente.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"A ordem pode modificar relações de tempo, causa, emoção e argumento entre os planos.","alternativeExplanations":{"V":"Incorreto. A montagem cria relações semânticas.","F":"Correto. Os planos não funcionam necessariamente de modo isolado."},"tags":["cinema","montagem","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cinema","montagem","ordem"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-03","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Fotografia","subtopic":"Exposição","difficulty":"medio","type":"true-false","statement":"Profundidade de campo depende apenas da abertura; distância focal e distância de foco não interferem.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Profundidade de campo é influenciada por múltiplos fatores, entre eles abertura, distância focal e distância de foco.","alternativeExplanations":{"V":"Incorreto. O fenômeno não depende de uma única variável.","F":"Correto. A afirmação simplifica excessivamente o controle fotográfico."},"tags":["fotografia","profundidade-de-campo","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["fotografia","profundidade-de-campo","parametros"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-04","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cultura popular","subtopic":"Patrimônio imaterial","difficulty":"medio","type":"true-false","statement":"Salvaguardar patrimônio imaterial exige impedir qualquer transformação da prática cultural ao longo do tempo.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Práticas vivas podem se transformar; salvaguarda procura sustentar condições de continuidade e transmissão.","alternativeExplanations":{"V":"Incorreto. Mudança não é incompatível com patrimônio vivo.","F":"Correto. Congelamento absoluto não é requisito de salvaguarda."},"tags":["cultura-popular","patrimonio","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cultura-popular","patrimonio","salvaguarda"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-05","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte contemporânea","subtopic":"Participação","difficulty":"medio","type":"true-false","statement":"Uma obra participativa garante automaticamente que artista e público possuam exatamente o mesmo poder de decisão.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Participação pode ocorrer em diferentes graus e não elimina automaticamente assimetrias de autoria ou poder.","alternativeExplanations":{"V":"Incorreto. É necessário analisar como as decisões são distribuídas.","F":"Correto. Participação nominal não equivale a igualdade."},"tags":["arte-contemporanea","participacao","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-contemporanea","participacao","poder"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-06","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Linguagem visual","subtopic":"Cor","difficulty":"medio","type":"true-false","statement":"O efeito de uma cor depende também das cores vizinhas; o mesmo tom pode parecer\n    mais intenso ou mais apagado conforme o contexto.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Percepção cromática é relacional: contraste simultâneo e contexto alteram a aparência percebida.","alternativeExplanations":{"V":"Correto. Cores não são percebidas de modo totalmente isolado.","F":"Incorreto. Relações cromáticas influenciam percepção."},"tags":["linguagem-visual","cor","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["linguagem-visual","cor","percepcao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-07","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"História da arte","subtopic":"Renascimento","difficulty":"medio","type":"true-false","statement":"O uso de perspectiva linear no Renascimento não significa que todas as obras renascentistas\n    tenham abandonado temas religiosos ou simbólicos.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Técnicas de representação espacial coexistiram com temas cristãos, mitológicos, retratos e outros repertórios.","alternativeExplanations":{"V":"Correto. Mudança formal não implica substituição total dos temas anteriores.","F":"Incorreto. É inadequado reduzir o Renascimento a uma ruptura temática absoluta."},"tags":["historia-da-arte","renascimento","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["historia-da-arte","renascimento","forma-e-tema"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-08","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte brasileira","subtopic":"Barroco","difficulty":"medio","type":"true-false","statement":"Analisar o Barroco mineiro como simples cópia europeia é suficiente, pois adaptações locais e condições coloniais não alteram sua compreensão histórica.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"A produção barroca brasileira envolve apropriações, condições locais, agentes e relações sociais específicas.","alternativeExplanations":{"V":"Incorreto. O contexto local é historicamente relevante.","F":"Correto. A afirmação reduz um processo complexo a cópia passiva."},"tags":["arte-brasileira","barroco","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-brasileira","barroco","apropriacao-cultural"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-09","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Modernismo","subtopic":"Semana de 1922","difficulty":"medio","type":"true-false","statement":"A Semana de Arte Moderna de 1922 pode ser entendida como marco simbólico,\n    mas o modernismo brasileiro não começou nem terminou inteiramente nos dias do evento.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Processos modernistas envolvem antecedentes e desdobramentos posteriores; a Semana é um marco, não um limite absoluto.","alternativeExplanations":{"V":"Correto. Movimentos artísticos se desenvolvem historicamente para além de um único evento.","F":"Incorreto. Reduzir todo o modernismo aos dias da Semana simplifica o processo."},"tags":["modernismo","antropofagia","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["modernismo","semana-de-1922","periodizacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-10","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Artes visuais","subtopic":"Composição","difficulty":"medio","type":"true-false","statement":"Em composição visual, equilíbrio não exige necessariamente simetria perfeita.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Uma composição pode obter equilíbrio assimétrico por distribuição de pesos visuais, cores, massas e vazios.","alternativeExplanations":{"V":"Correto. Simetria é uma possibilidade, não uma condição obrigatória.","F":"Incorreto. Equilíbrio visual pode ocorrer com elementos desiguais."},"tags":["artes-visuais","composicao","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["artes-visuais","composicao","equilibrio"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-11","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Música","subtopic":"Elementos sonoros","difficulty":"medio","type":"true-false","statement":"Uma pausa pode ter função rítmica e expressiva em uma música, mesmo sendo ausência momentânea de som.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Silêncios possuem duração e posição no tempo e podem organizar expectativa, fraseado e contraste.","alternativeExplanations":{"V":"Correto. O silêncio participa da estrutura musical.","F":"Incorreto. Ausência acústica não significa ausência de função musical."},"tags":["musica","ritmo","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["musica","silencio","ritmo"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-m-12","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Teatro","subtopic":"Representação","difficulty":"medio","type":"true-false","statement":"Romper a quarta parede sempre elimina a narrativa e impede qualquer envolvimento emocional do espectador.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"A ruptura pode produzir distanciamento, humor, cumplicidade ou outros efeitos sem necessariamente destruir narrativa ou emoção.","alternativeExplanations":{"V":"Incorreto. Os efeitos dependem da encenação.","F":"Correto. O uso de 'sempre' torna a afirmação inadequada."},"tags":["teatro","quarta-parede","vestibulares","medio"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["teatro","quarta-parede","recepcao"],"origin":"nabulab"},

  {"id":"arte-vest-v1-mc-a-01","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Fotografia","subtopic":"Exposição","difficulty":"avancado","type":"multiple-choice","statement":"Um fotógrafo escolhe profundidade de campo muito curta para isolar uma pessoa em uma multidão.\n    Outro mantém tudo em foco para mostrar relações entre personagem e ambiente.\n\n    Qual conclusão é mais adequada?","alternatives":[{"id":"A","text":"profundidade de campo também funciona como decisão narrativa, pois orienta a atenção e as relações visuais na imagem"},{"id":"B","text":"profundidade de campo é exclusivamente um problema técnico sem efeito de sentido"},{"id":"C","text":"manter tudo em foco impede qualquer composição visual"},{"id":"D","text":"desfoque sempre torna uma fotografia artisticamente superior"}],"correctAnswer":"A","explanation":"Escolhas técnicas de foco têm efeitos expressivos: podem separar figura e fundo ou integrar diferentes planos espaciais.","alternativeExplanations":{"A":"Correta. Escolhas técnicas de foco têm efeitos expressivos: podem separar figura e fundo ou integrar diferentes planos espaciais.","B":"A escolha altera o que recebe atenção e como o espaço é lido.","C":"Nitidez ampla também pode ser usada compositivamente.","D":"Não existe superioridade automática; a escolha depende da intenção."},"tags":["fotografia","profundidade-de-campo","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["fotografia","profundidade-de-campo","narrativa-visual"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-02","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cultura popular","subtopic":"Patrimônio imaterial","difficulty":"avancado","type":"multiple-choice","statement":"Uma manifestação é registrada como patrimônio imaterial. Depois, empresas de turismo passam\n    a exigir apresentações em horários e formatos voltados aos visitantes, enquanto praticantes locais\n    discutem se isso altera o sentido da tradição.\n\n    Qual questão é central para a análise?","alternatives":[{"id":"A","text":"o registro torna a prática automaticamente imune a mudanças"},{"id":"B","text":"como reconhecimento patrimonial, mercado e participação comunitária podem disputar os sentidos e formas de continuidade da prática"},{"id":"C","text":"turismo e patrimônio nunca podem coexistir"},{"id":"D","text":"apenas especialistas externos podem definir o significado da tradição"}],"correctAnswer":"B","explanation":"Patrimonialização pode gerar visibilidade e recursos, mas também novas pressões, negociações e conflitos sobre autoria, uso e transformação.","alternativeExplanations":{"A":"O reconhecimento não congela a manifestação.","B":"Correta. Patrimonialização pode gerar visibilidade e recursos, mas também novas pressões, negociações e conflitos sobre autoria, uso e transformação.","C":"Podem coexistir, mas exigem análise de efeitos e relações de poder.","D":"Os grupos praticantes são agentes fundamentais na atribuição de valor e continuidade."},"tags":["cultura-popular","patrimonio","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cultura-popular","patrimonializacao","mercantilizacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-03","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte contemporânea","subtopic":"Participação","difficulty":"avancado","type":"multiple-choice","statement":"Um projeto artístico convida moradores de um bairro a discutir problemas urbanos,\n    mas o artista define sozinho quem participa, quais falas serão publicadas e como o resultado será exibido.\n\n    Qual crítica é mais pertinente?","alternatives":[{"id":"A","text":"qualquer obra com participação é automaticamente democrática"},{"id":"B","text":"a presença de autoria artística impede qualquer colaboração"},{"id":"C","text":"a retórica de participação deve ser confrontada com a distribuição real de poder e autoria no projeto"},{"id":"D","text":"questões éticas são irrelevantes em arte relacional"}],"correctAnswer":"C","explanation":"Projetos participativos podem criar colaboração, mas também reproduzir assimetrias se decisões centrais permanecerem concentradas.","alternativeExplanations":{"A":"Participação formal não garante igualdade decisória.","B":"Autoria e colaboração podem assumir diferentes arranjos.","C":"Correta. Projetos participativos podem criar colaboração, mas também reproduzir assimetrias se decisões centrais permanecerem concentradas.","D":"Relações entre pessoas fazem ética e poder especialmente relevantes."},"tags":["arte-contemporanea","participacao","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-contemporanea","participacao","etica-e-autoria"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-04","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Linguagem visual","subtopic":"Cor","difficulty":"avancado","type":"multiple-choice","statement":"Uma campanha usa vermelho para indicar perigo em um cartaz e para sugerir celebração em outro.\n    A cor física é semelhante, mas o sentido muda por causa de imagens, texto e contexto cultural.\n\n    Qual conclusão é mais adequada?","alternatives":[{"id":"A","text":"cada cor possui um significado universal independente de contexto"},{"id":"B","text":"significado cultural elimina qualquer efeito perceptivo da cor"},{"id":"C","text":"cor nunca participa da construção de sentido"},{"id":"D","text":"cor possui propriedades perceptivas, mas seus significados também dependem de contexto e convenções culturais"}],"correctAnswer":"D","explanation":"Não existe correspondência universal e fixa entre uma cor e um único significado; associações são produzidas por contexto, uso e repertório cultural.","alternativeExplanations":{"A":"Associações cromáticas variam entre culturas e situações.","B":"Dimensões perceptivas e culturais coexistem.","C":"Ela pode ter forte função semântica e afetiva.","D":"Correta. Não existe correspondência universal e fixa entre uma cor e um único significado; associações são produzidas por contexto, uso e repertório cultural."},"tags":["linguagem-visual","cor","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["linguagem-visual","cor","significado-cultural"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-05","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"História da arte","subtopic":"Renascimento","difficulty":"avancado","type":"multiple-choice","statement":"Um historiador da arte observa que a perspectiva linear não é apenas uma técnica neutra:\n    ela pressupõe um ponto de vista organizado, fixa uma posição ideal do observador e\n    transforma o espaço em algo mensurável.\n\n    Qual interpretação melhor desenvolve essa observação?","alternatives":[{"id":"A","text":"a perspectiva pode ser analisada também como forma histórica de organizar visualmente a relação entre sujeito e espaço"},{"id":"B","text":"a perspectiva prova que a visão humana funciona exatamente como uma câmera em qualquer situação"},{"id":"C","text":"qualquer obra sem ponto de fuga é tecnicamente incapaz de representar espaço"},{"id":"D","text":"o uso de geometria elimina qualquer dimensão cultural da imagem"}],"correctAnswer":"A","explanation":"Além do efeito óptico, a perspectiva pode ser estudada como convenção cultural que traduz determinadas concepções de espaço, visão e racionalidade.","alternativeExplanations":{"A":"Correta. Além do efeito óptico, a perspectiva pode ser estudada como convenção cultural que traduz determinadas concepções de espaço, visão e racionalidade.","B":"A perspectiva é uma convenção construída e não uma reprodução total da percepção.","C":"Há muitas outras estratégias históricas de representação espacial.","D":"Técnica e cultura não são dimensões excludentes."},"tags":["historia-da-arte","renascimento","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["historia-da-arte","perspectiva","convencao-visual"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-06","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte brasileira","subtopic":"Barroco","difficulty":"avancado","type":"multiple-choice","statement":"Uma igreja barroca construída em Minas Gerais combina modelos europeus, materiais disponíveis\n    localmente, mão de obra de diferentes origens sociais e soluções adaptadas ao espaço colonial.\n\n    Qual abordagem histórica é mais produtiva?","alternatives":[{"id":"A","text":"classificar a obra apenas pela nacionalidade de um modelo europeu"},{"id":"B","text":"analisar a obra como resultado de circulação de modelos e reelaborações locais dentro de relações sociais coloniais"},{"id":"C","text":"considerar contexto social irrelevante porque apenas a forma importa"},{"id":"D","text":"tratar toda produção colonial como artisticamente homogênea"}],"correctAnswer":"B","explanation":"Obras barrocas podem ser estudadas como produtos de trocas culturais, trabalho especializado, religião, economia e hierarquias coloniais.","alternativeExplanations":{"A":"Isso apaga processos locais de adaptação e produção.","B":"Correta. Obras barrocas podem ser estudadas como produtos de trocas culturais, trabalho especializado, religião, economia e hierarquias coloniais.","C":"Forma e contexto podem ser analisados conjuntamente.","D":"Existem diferenças regionais, cronológicas e de agentes."},"tags":["arte-brasileira","barroco","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-brasileira","barroco","circulacao-e-adaptacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-07","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Modernismo","subtopic":"Semana de 1922","difficulty":"avancado","type":"multiple-choice","statement":"O Manifesto Antropófago transforma a imagem colonial do \"canibal\" em metáfora positiva:\n    devorar influências para recriá-las.\n\n    Qual operação crítica está envolvida?","alternatives":[{"id":"A","text":"defender pureza cultural sem qualquer contato externo"},{"id":"B","text":"restaurar os padrões acadêmicos europeus sem transformação"},{"id":"C","text":"reverter um estereótipo colonial e convertê-lo em estratégia de autonomia cultural"},{"id":"D","text":"negar qualquer relação entre arte e identidade cultural"}],"correctAnswer":"C","explanation":"A antropofagia ressignifica uma imagem usada historicamente para marcar alteridade e a transforma em princípio de apropriação ativa e invenção.","alternativeExplanations":{"A":"A metáfora depende justamente da incorporação de influências.","B":"A proposta é crítica e recriadora.","C":"Correta. A antropofagia ressignifica uma imagem usada historicamente para marcar alteridade e a transforma em princípio de apropriação ativa e invenção.","D":"O manifesto participa diretamente do debate sobre identidade e cultura."},"tags":["modernismo","antropofagia","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["modernismo","antropofagia","pos-colonialidade"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-08","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Artes visuais","subtopic":"Composição","difficulty":"avancado","type":"multiple-choice","statement":"Duas capas usam os mesmos elementos — fotografia, título e logotipo —, mas produzem leituras\n    muito diferentes porque mudam escala, proximidade, alinhamento e contraste entre eles.\n\n    Qual conclusão é mais adequada?","alternatives":[{"id":"A","text":"se os elementos são os mesmos, o significado visual necessariamente permanece idêntico"},{"id":"B","text":"apenas o texto verbal produz significado em uma capa"},{"id":"C","text":"composição é um aspecto puramente decorativo sem efeito de leitura"},{"id":"D","text":"o sentido visual resulta também das relações compositivas entre elementos, não apenas de seus conteúdos isolados"}],"correctAnswer":"D","explanation":"Composição organiza percurso do olhar, hierarquia, tensão, proximidade e relações semânticas entre componentes.","alternativeExplanations":{"A":"Relações formais alteram leitura e ênfase.","B":"Imagem, tipografia e organização espacial também significam.","C":"Ela orienta atenção e interpretação.","D":"Correta. Composição organiza percurso do olhar, hierarquia, tensão, proximidade e relações semânticas entre componentes."},"tags":["artes-visuais","composicao","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["artes-visuais","composicao","leitura-visual"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-09","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Música","subtopic":"Elementos sonoros","difficulty":"avancado","type":"multiple-choice","statement":"Em uma obra, um padrão rítmico originalmente associado a uma tradição popular é deslocado,\n    fragmentado e superposto a outra métrica. O ouvinte ainda reconhece traços da referência,\n    mas sua função foi transformada.\n\n    Qual análise é mais produtiva?","alternatives":[{"id":"A","text":"o ritmo pode atuar simultaneamente como estrutura temporal e como signo cultural ressignificado pela composição"},{"id":"B","text":"um ritmo perde qualquer dimensão cultural quando entra numa obra nova"},{"id":"C","text":"qualquer citação rítmica é necessariamente cópia literal"},{"id":"D","text":"métrica e ritmo são conceitos sem relação"}],"correctAnswer":"A","explanation":"Elementos musicais possuem dimensão formal e histórica; apropriação e transformação podem alterar sentidos de uma referência rítmica.","alternativeExplanations":{"A":"Correta. Elementos musicais possuem dimensão formal e histórica; apropriação e transformação podem alterar sentidos de uma referência rítmica.","B":"Referências podem continuar reconhecíveis e adquirir novos sentidos.","C":"Fragmentação e superposição mostram transformação.","D":"Métrica organiza ciclos de pulsos e interage com padrões rítmicos."},"tags":["musica","ritmo","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["musica","ritmo","apropriacao-cultural"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-10","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Teatro","subtopic":"Representação","difficulty":"avancado","type":"multiple-choice","statement":"Uma peça apresenta uma cena emocionalmente intensa. Logo depois, um ator abandona o personagem,\n    explica como a cena foi construída e mostra ao público os objetos usados para produzir a ilusão.\n\n    Qual interpretação é mais adequada?","alternatives":[{"id":"A","text":"a revelação técnica elimina necessariamente qualquer sentido político"},{"id":"B","text":"a encenação alterna imersão e distanciamento para problematizar a própria construção do espetáculo"},{"id":"C","text":"o ator deixa de fazer teatro ao reconhecer a plateia"},{"id":"D","text":"a quarta parede é uma regra obrigatória em qualquer tradição cênica"}],"correctAnswer":"B","explanation":"Ao revelar os mecanismos de representação, a peça impede que a ficção seja recebida apenas como realidade naturalizada.","alternativeExplanations":{"A":"Expor a construção pode inclusive reforçar uma leitura crítica.","B":"Correta. Ao revelar os mecanismos de representação, a peça impede que a ficção seja recebida apenas como realidade naturalizada.","C":"Metateatro continua sendo teatro.","D":"Muitas formas teatrais não dependem dessa convenção."},"tags":["teatro","quarta-parede","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["teatro","representacao","metalinguagem"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-11","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Dança","subtopic":"Criação","difficulty":"avancado","type":"multiple-choice","statement":"Em uma performance improvisada, cada bailarino responde aos movimentos dos demais.\n    Não existe uma sequência fixa, mas decisões individuais alteram continuamente\n    as possibilidades do grupo.\n\n    Qual conceito ajuda a compreender a composição resultante?","alternatives":[{"id":"A","text":"autoria exclusivamente individual e independente"},{"id":"B","text":"reprodução literal de uma partitura fechada"},{"id":"C","text":"criação emergente baseada em interação e atenção compartilhada"},{"id":"D","text":"ausência completa de organização"}],"correctAnswer":"C","explanation":"A forma não está totalmente pronta antes da execução; ela emerge de respostas entre corpos, espaço, tempo e regras de interação.","alternativeExplanations":{"A":"As decisões são interdependentes.","B":"A sequência não está previamente fixada.","C":"Correta. A forma não está totalmente pronta antes da execução; ela emerge de respostas entre corpos, espaço, tempo e regras de interação.","D":"A interação e as regras funcionam como princípios organizadores."},"tags":["danca","improvisacao","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["danca","improvisacao","composicao-em-tempo-real"],"origin":"nabulab"},
  {"id":"arte-vest-v1-mc-a-12","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cinema","subtopic":"Montagem","difficulty":"avancado","type":"multiple-choice","statement":"Um documentário alterna imagens de luxo, filas de desemprego e discursos oficiais sobre crescimento.\n    Nenhum plano afirma verbalmente uma conclusão, mas a justaposição cria uma leitura crítica.\n\n    Qual operação está em jogo?","alternatives":[{"id":"A","text":"o documentário deixa de ter qualquer ponto de vista por não usar narrador"},{"id":"B","text":"as imagens permanecem semanticamente independentes"},{"id":"C","text":"a crítica só poderia existir se cada plano tivesse texto explicativo"},{"id":"D","text":"a montagem estabelece uma relação argumentativa entre imagens, produzindo sentido pela justaposição"}],"correctAnswer":"D","explanation":"A organização dos planos pode funcionar como argumento audiovisual, criando contraste e comentário sem depender de narração explícita.","alternativeExplanations":{"A":"Escolhas de montagem já expressam perspectiva.","B":"A justaposição cria relações entre elas.","C":"O audiovisual pode argumentar por relações visuais e sonoras.","D":"Correta. A organização dos planos pode funcionar como argumento audiovisual, criando contraste e comentário sem depender de narração explícita."},"tags":["cinema","montagem","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cinema","montagem","argumentacao-audiovisual"],"origin":"nabulab"},

  {"id":"arte-vest-v1-vf-a-01","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte contemporânea","subtopic":"Participação","difficulty":"avancado","type":"true-false","statement":"Em arte participativa, avaliar quem define as regras, quem pode falar e quem controla\n    a documentação pode ser tão importante quanto descrever a interação em si.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"A análise crítica considera estruturas de autoria, poder, inclusão e representação que organizam a participação.","alternativeExplanations":{"V":"Correto. Interação não ocorre fora de relações de poder.","F":"Incorreto. Esses elementos podem alterar profundamente o sentido político e artístico do projeto."},"tags":["arte-contemporanea","participacao","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-contemporanea","participacao","poder-e-representacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-02","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Linguagem visual","subtopic":"Cor","difficulty":"avancado","type":"true-false","statement":"Os significados simbólicos das cores são universais: uma mesma cor comunica necessariamente a mesma ideia em qualquer sociedade e período histórico.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Associações cromáticas dependem de convenções, contextos e histórias culturais e não são universais.","alternativeExplanations":{"V":"Incorreto. O significado simbólico varia socialmente.","F":"Correto. A afirmação universaliza uma convenção cultural."},"tags":["linguagem-visual","cor","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["linguagem-visual","cor","percepcao-e-cultura"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-03","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"História da arte","subtopic":"Renascimento","difficulty":"avancado","type":"true-false","statement":"Tratar a perspectiva linear como convenção histórica não significa negar sua eficácia\n    para produzir profundidade visual; significa reconhecer que modos de representar o espaço\n    também são culturalmente construídos.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Uma técnica pode funcionar visualmente e, ao mesmo tempo, carregar pressupostos históricos sobre visão, espaço e observador.","alternativeExplanations":{"V":"Correto. Eficácia formal e historicidade podem coexistir.","F":"Incorreto. Reconhecer historicidade não implica dizer que a técnica não produz efeito espacial."},"tags":["historia-da-arte","renascimento","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["historia-da-arte","perspectiva","historicidade"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-04","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Arte brasileira","subtopic":"Barroco","difficulty":"avancado","type":"true-false","statement":"Reconhecer influências europeias no Barroco brasileiro obriga a concluir que não houve nenhuma reelaboração local.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Influência e transformação local não são excludentes; modelos podem ser apropriados e modificados.","alternativeExplanations":{"V":"Incorreto. A circulação cultural não equivale a cópia integral.","F":"Correto. O enunciado elimina indevidamente a agência local."},"tags":["arte-brasileira","barroco","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["arte-brasileira","barroco","influencia-e-recriacao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-05","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Modernismo","subtopic":"Semana de 1922","difficulty":"avancado","type":"true-false","statement":"A antropofagia modernista pode ser lida como crítica à ideia de que culturas periféricas\n    só podem copiar passivamente centros culturais considerados superiores.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"A proposta enfatiza apropriação transformadora e produção ativa de linguagem, questionando hierarquias culturais.","alternativeExplanations":{"V":"Correto. A metáfora antropofágica redefine a relação com influências externas.","F":"Incorreto. O movimento problematiza justamente a dependência cultural passiva."},"tags":["modernismo","antropofagia","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["modernismo","antropofagia","hierarquia-cultural"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-06","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Artes visuais","subtopic":"Composição","difficulty":"avancado","type":"true-false","statement":"Se duas composições usam exatamente os mesmos elementos, sua organização espacial não pode alterar hierarquia, tensão ou sentido visual.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Posição, escala, proximidade e contraste mudam o peso e as relações entre elementos.","alternativeExplanations":{"V":"Incorreto. Composição participa diretamente da construção de leitura.","F":"Correto. O mesmo material pode produzir sentidos diferentes."},"tags":["artes-visuais","composicao","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["artes-visuais","composicao","peso-visual"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-07","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Música","subtopic":"Elementos sonoros","difficulty":"avancado","type":"true-false","statement":"Analisar um padrão rítmico apenas pela duração das notas pode ser insuficiente quando\n    sua função cultural, o contexto de execução e a acentuação também influenciam seu sentido.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"A análise musical pode articular estrutura sonora, performance e contexto histórico-cultural.","alternativeExplanations":{"V":"Correto. Forma e contexto podem contribuir conjuntamente para o significado.","F":"Incorreto. A duração é importante, mas não esgota todas as dimensões do ritmo."},"tags":["musica","ritmo","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["musica","ritmo","contexto-cultural"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-08","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Teatro","subtopic":"Representação","difficulty":"avancado","type":"true-false","statement":"A quarta parede é condição universal de qualquer forma teatral e nunca pode ser rompida sem que a obra deixe de ser teatro.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Muitas tradições teatrais dialogam diretamente com o público; a quarta parede é uma convenção histórica, não uma exigência universal.","alternativeExplanations":{"V":"Incorreto. Teatro não depende obrigatoriamente dessa convenção.","F":"Correto. O enunciado transforma uma possibilidade formal em regra absoluta."},"tags":["teatro","quarta-parede","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["teatro","quarta-parede","convencao-historica"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-09","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Dança","subtopic":"Criação","difficulty":"avancado","type":"true-false","statement":"Uma improvisação pode ser rigorosamente estruturada sem ter cada movimento determinado de antemão.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"Estrutura pode definir relações, limites, tarefas e parâmetros, enquanto a solução corporal concreta permanece aberta.","alternativeExplanations":{"V":"Correto. Estrutura e abertura não são opostos absolutos.","F":"Incorreto. Determinação total de passos é apenas uma das formas possíveis de organização."},"tags":["danca","improvisacao","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["danca","improvisacao","estrutura"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-10","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cinema","subtopic":"Montagem","difficulty":"avancado","type":"true-false","statement":"Uma montagem de continuidade é neutra porque, quando os cortes ficam pouco perceptíveis, deixam de existir escolhas de seleção e organização.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Mesmo cortes discretos resultam de escolhas de enquadramento, duração, ordem e continuidade.","alternativeExplanations":{"V":"Incorreto. Invisibilidade formal não elimina construção.","F":"Correto. Toda montagem organiza material audiovisual."},"tags":["cinema","montagem","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cinema","montagem","convencao"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-11","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Fotografia","subtopic":"Exposição","difficulty":"avancado","type":"true-false","statement":"Duas fotografias com a mesma exposição luminosa podem ter profundidades de campo diferentes,\n    pois combinações distintas de abertura, velocidade e sensibilidade podem manter a exposição.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"V","explanation":"A mesma quantidade de luz pode ser obtida por combinações diferentes do triângulo de exposição, enquanto a abertura altera a profundidade de campo.","alternativeExplanations":{"V":"Correto. Exposição equivalente não implica resultado visual idêntico.","F":"Incorreto. Parâmetros equivalentes em luz podem produzir efeitos distintos de foco e movimento."},"tags":["fotografia","profundidade-de-campo","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["fotografia","exposicao","profundidade-de-campo"],"origin":"nabulab"},
  {"id":"arte-vest-v1-vf-a-12","area":"Linguagens","subject":"arte","subjectName":"Arte","topic":"Cultura popular","subtopic":"Patrimônio imaterial","difficulty":"avancado","type":"true-false","statement":"Depois que uma prática é reconhecida oficialmente como patrimônio imaterial, conflitos sobre turismo, representação e autoria deixam de existir.","alternatives":[{"id":"V","text":"Verdadeiro"},{"id":"F","text":"Falso"}],"correctAnswer":"F","explanation":"Patrimonialização pode inclusive criar novas disputas sobre visibilidade, uso, representação e recursos.","alternativeExplanations":{"V":"Incorreto. Reconhecimento oficial não neutraliza conflitos sociais.","F":"Correto. Patrimônio é também um processo político e social."},"tags":["cultura-popular","patrimonio","vestibulares","avancado"],"examTags":["enem","unesp"],"educationLevel":"ensino-medio","skills":["cultura-popular","patrimonio","politicas-culturais"],"origin":"nabulab"}
];